#include <Arduino.h>
#include <DHT.h>
#include <TM1637Display.h>
#include <math.h>

const uint8_t FAN_PIN = 5;
const uint8_t DHT_PIN = 7;
const float FAN_THRESHOLD_C = 30.0f;
DHT sensor(DHT_PIN, DHT11);
TM1637Display display(4, 2);
unsigned long lastRead = 0;
bool firstRead = true;

void setup() {
  pinMode(FAN_PIN, OUTPUT);
  analogWrite(FAN_PIN, 0);
  sensor.begin();
  display.setBrightness(7);
  display.clear();
}

void loop() {
  unsigned long now = millis();
  if (firstRead || now - lastRead >= 2000UL) {
    firstRead = false;
    lastRead = now;
    float temperature = sensor.readTemperature();
    if (!isnan(temperature)) {
      display.showNumberDec((int)roundf(temperature), false);
      analogWrite(FAN_PIN, temperature > FAN_THRESHOLD_C ? 255 : 0);
    }
  }
}
